// Package pgversion is R2.4's capability matrix: the PG 13–18 view/column table
// itself (matrix_data.go, generated by scripts/gen-pgmatrix.py from the
// postgresql.org docs) and the accessors every SQL collector resolves its query
// through.
//
// The package exists as a seam. R2.1's fourth descriptor field is "PG-version
// applicability", and internal/collector/collector.go declares it as
// `type Applicability func(pgMajor int) bool` with a comment saying the answer
// comes from this package — which was the phase's second commit, so the func
// type had to exist before the matrix did. AppliesTo is that answer for a single
// view, and the compile-time proof that it fits the seam is the
// `var _ Applicability = pgversion.AppliesTo(pgversion.ViewStatWAL)` line in
// internal/collector/collector_test.go (it lives there because importing
// collector from this package would be an import cycle).
//
// R2.4's wording is deliberate about shape — "per-view column sets per major,
// not a rename table" — and the reason is the bgwriter case: a rename table
// written at PG17 records bgwriter shrinking 11 columns to 4 and loses four
// still-valid checkpoint families that moved to a separate view. Column sets
// answer that per view, so a moved column is simply absent from one view's set
// and present in another's. succession.go carries the rename/move/split cases
// *alongside* the sets, for the callers that need to know a column's history
// (R3.2's Load-by-IO derivation, the R9.4 metric naming) rather than its shape.
package pgversion

import (
	"fmt"
	"sort"
	"strings"
)

// View names a PostgreSQL relation the matrix holds columns for. The declared
// constants live in matrix_data.go; the type is here so the generated file holds
// only data.
//
// A View is a string rather than an int with a String() method because the
// string *is* the SQL fragment R2.5 qualifies and the name the docs use, so
// there is no second spelling to keep in sync — and a typo in a View constant
// reads as wrong in a diff, which an int does not.
type View string

// The PostgreSQL majors the matrix covers.
//
// R2.4's headline range is "PG 15–18" because that is what CNPG 1.30 supports
// (R13.9), but the table covers 13 and 14 as well: R13.9 documents them as
// fixture-tested SQL-layer rows, and R2.4's own first enumerated case is a
// *PG13* rename (`total_time`→`total_exec_time`). A matrix that starts at 15
// cannot encode a PG13 rename, so the data spans six majors while the supported
// set is four. Majors() and CNPGSupported() are the two answers.
const (
	Major13 = 13
	Major14 = 14
	Major15 = 15
	Major16 = 16
	Major17 = 17
	Major18 = 18
)

// majors is the ordered list Majors returns, and the set Validate accepts as a
// map key. A table keyed by major 19 or 0 is a typo, not a future major: R13.9
// fixes the supported range, so widening it is a spec change and lands here
// first.
var majors = []int{Major13, Major14, Major15, Major16, Major17, Major18}

// cnpgSupported is R13.9's PostgreSQL axis for CNPG 1.30: 15–18. Kept separate
// from majors so "in the matrix" and "runnable against our reference fleet" stay
// two different questions — the discovery layer needs the second, R16.1's
// six-major test needs the first.
var cnpgSupported = []int{Major15, Major16, Major17, Major18}

// Majors returns every major the matrix has data for, ascending. The returned
// slice is a copy: callers sort and filter it without mutating the package's.
func Majors() []int { return append([]int(nil), majors...) }

// CNPGSupported returns the majors CNPG 1.30 can actually run (R13.9: 15–18),
// ascending. Discovery uses this to decide whether a cluster it found is in
// scope; the matrix's extra 13/14 rows exist for the SQL layer and the tests.
func CNPGSupported() []int { return append([]int(nil), cnpgSupported...) }

// IsSupported reports whether major is one CNPG 1.30 can run (R13.9's axis).
// It is Exists-for-majors, not Exists-for-views: a major with no data at all
// must never answer true here, which is why it checks majors, not the table.
func IsSupported(major int) bool {
	for _, m := range cnpgSupported {
		if m == major {
			return true
		}
	}
	return false
}

// columnCache is columnsByMajor with the raw strings split into slices.
//
// The generated file stores each set as one raw string (that is what makes the
// generator's output diffable, and what lets a reviewer eyeball 32 column names
// at once), so Columns splits on whitespace. Splitting once at init rather than
// per call keeps Columns allocation-light for the hot path — a collector that
// polls thirteen views builds thirteen strings per round, not thirteen thousand.
var columnCache = splitColumns(columnsByMajor)

func splitColumns(table map[View]map[int]string) map[View]map[int][]string {
	out := make(map[View]map[int][]string, len(table))
	for view, per := range table {
		inner := make(map[int][]string, len(per))
		for major, set := range per {
			inner[major] = strings.Fields(set)
		}
		out[view] = inner
	}
	return out
}

// Columns returns view's column list on major, and false on a major where the
// view does not exist.
//
// The false matters more than the list. pg_stat_checkpointer at PG16,
// pg_stat_io at PG15, and pg_stat_wal at PG13 have no columns because they have
// no *view*: an empty slice would render as `SELECT FROM pg_catalog.x`, a
// syntax error at runtime, and every collector would have to remember to
// distinguish "no columns" from "no view". R2.4's whole claim is that absence is
// per-(view, major) data, so absence is what the accessor returns.
//
// The returned slice is a copy, so a caller that sorts or truncates it (a
// collector projecting a subset) cannot corrupt the shared table.
func Columns(view View, major int) ([]string, bool) {
	per, ok := columnCache[view]
	if !ok {
		return nil, false
	}
	cols, ok := per[major]
	if !ok {
		return nil, false
	}
	return append([]string(nil), cols...), true
}

// Exists reports whether view exists on major. It is Columns's second return
// value named, because the callers that want only the boolean (R2.1's
// applicability check, R9.8's "is this metric name valid on this major") read
// better than `_, ok := Columns(...)`.
func Exists(view View, major int) bool {
	_, ok := Columns(view, major)
	return ok
}

// Query returns the SELECT statement R2.5 requires for view on major: every
// column named explicitly, and the relation schema-qualified.
//
// R2.5's rule is the reason the projection is explicit rather than `SELECT *`:
// `SELECT *` on a view whose columns changed in a minor release silently changes
// the shape of the row a collector scans, and R2.4's column sets are the thing
// that makes the projection correct per major. Schema qualification is R2.5's
// other half — CNPG 1.29.1 hardened its exporter the same way against
// search_path shadowing.
//
// The statement is the projection only. R2.7's BEGIN READ ONLY / statement_timeout
// wrapper and R2.8's `application_name = 'pgsi_confirmed'` exclusion are
// per-view-group and per-collector concerns, not per-view ones, so the collector
// adds them; a matrix that emitted `… WHERE application_name <> …` for every
// view would be wrong for the nine views that have no application_name column.
func Query(view View, major int) (string, bool) {
	cols, ok := Columns(view, major)
	if !ok {
		return "", false
	}
	q := "SELECT " + strings.Join(cols, ", ") + " FROM " + Schema(view) + "." + string(view)
	return q, true
}

// Schema returns the schema R2.5 qualifies view with.
//
// Everything in pg_catalog is `pg_catalog.`. The two pg_stat_statements
// relations are the exception R2.5 itself names (`pg_stat_statements.…`): the
// extension's objects live in the extension's own schema, which is the
// convention CNPG's exporter spells that way. A cluster that created the
// extension in a different schema needs the override R3.1's presence detection
// supplies, not a guess from this table — which is why the answer here is the
// convention and the collector is expected to confirm it via R3.1 first.
func Schema(view View) string {
	switch view {
	case ViewStatStatements, ViewStatStatementsInfo:
		return "pg_stat_statements"
	default:
		return "pg_catalog"
	}
}

// Views returns every view the matrix has data for on major, sorted. Used by
// the R9.8/R9.12 cross-checks (which need "every metric this major can produce")
// and by the R16.1 tests. An empty result for a major outside 13–18 is the
// correct answer, not an error.
func Views(major int) []View {
	var out []View
	for view, per := range columnCache {
		if _, ok := per[major]; ok {
			out = append(out, view)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i] < out[j] })
	return out
}

// AppliesTo returns R2.1's PG-version applicability for one view, as the
// collector.Applicability-shaped func the framework stores on a Descriptor:
// the collector may run against a cluster whose major has this view.
//
// It is per-view because that is what the matrix can answer honestly. A
// Descriptor that reads three views (the R2.1 io collector reads
// pg_stat_io/pg_stat_slru/pg_stat_bgwriter) needs the conjunction of three
// AppliesTo results, and the collector composes that itself rather than the
// matrix guessing which of its views are load-bearing. For a view that exists on
// every supported major the result is a func that always returns true, which is
// the same answer collector.AllMajors gives — the difference is that this one is
// derived from the table instead of asserted.
func AppliesTo(view View) func(int) bool {
	return func(major int) bool { return Exists(view, major) }
}

// Status is one cell of R13.9's compatibility matrix.
//
// R13.9's vocabulary is exactly these four values and its stated point is "no
// silent claims", so the values are a named type: an unset cell is the empty
// Status, which is not one of the four and therefore shows up as a bug rather
// than as a plausible-looking blank.
type Status string

// The four cells R13.9 allows, verbatim.
const (
	StatusTested     Status = "tested"
	StatusFixture    Status = "fixture"
	StatusImpossible Status = "impossible"
	StatusUntested   Status = "untested"
)

// statusByMajor is R13.9's PostgreSQL axis, with the note each cell carries.
//
// The 13/14 rows are where R13.9's two readings meet. The spec's cell is
// `impossible` — CNPG 1.30 cannot run them, PG 14 support ending 2026-11-12 —
// and the same sentence says they are "documented as fixture-tested SQL-layer
// rows only". The cell reports the CNPG answer, because that is the axis the
// matrix is drawn on, and the note carries the SQL-layer half so the cell cannot
// be read as "we know nothing about PG13 SQL". R2.4's PG13 rename case is the
// proof we do.
var statusByMajor = map[int]struct {
	status Status
	note   string
}{
	Major13: {
		StatusImpossible,
		"CNPG 1.30 cannot run PG 13 (R13.9); the SQL layer is fixture-tested only, " +
			"and it is the major R2.4's total_time→total_exec_time case comes from",
	},
	Major14: {
		StatusImpossible,
		"CNPG 1.30 cannot run PG 14 (support ended 2026-11-12, R13.9); the SQL layer " +
			"is fixture-tested only",
	},
	Major15: {
		StatusUntested,
		"supported by CNPG 1.30 but not present in the reference environment " +
			"(which runs 16.11 and 17.11), so no live measurement exists",
	},
	Major16: {
		StatusTested,
		"PG 16.11 measured on the reference environment (R13.9's one 16 cell)",
	},
	Major17: {
		StatusTested,
		"PG 17.11 measured on the reference environment (R13.9's one 17 cell)",
	},
	Major18: {
		StatusUntested,
		"supported by CNPG 1.30 but not present in the reference environment; " +
			"R2.4's pg_stat_wal 9→5 and op_bytes cases are from the docs, not measured",
	},
}

// StatusOf returns R13.9's PostgreSQL-axis cell for one major and the note that
// makes it non-silent. ok is false for a major outside 13–18, which is the
// difference between "no cell" and a cell that claims something.
func StatusOf(major int) (status Status, note string, ok bool) {
	cell, ok := statusByMajor[major]
	return cell.status, cell.note, ok
}

// Validate reports every inconsistency it finds in the shipped table.
//
// The generated file is machine-written, so most of what Validate checks is
// machine-checkable-by-construction there and therefore cheap here — but the
// construction argument only holds if the generator is the only writer. The
// header says DO NOT EDIT and headers get edited anyway, so this is the
// executable version of that sentence, and matrix_test.go runs it against both
// the real table and mutated copies of it.
func Validate() error { return validate(columnsByMajor) }

func validate(table map[View]map[int]string) error {
	var errs []string
	add := func(format string, args ...any) {
		errs = append(errs, fmt.Sprintf(format, args...))
	}

	known := map[int]bool{}
	for _, m := range majors {
		known[m] = true
	}

	// A column set reused across two different views. The generated file names
	// each set after one view, so a set string appearing under pg_stat_wal and
	// pg_stat_bgwriter means one of the two rows was edited by hand — the
	// copy-paste this file's shape exists to prevent.
	owners := map[string]View{}

	for view, per := range table {
		if err := checkViewName(view); err != nil {
			add("%s: %v", view, err)
		}
		for major, set := range per {
			if !known[major] {
				add("%s: major %d is not a major the matrix covers", view, major)
				continue
			}
			cols := strings.Fields(set)
			if len(cols) == 0 {
				add("%s %d: empty column set (a `SELECT FROM %s` would be a syntax error)",
					view, major, view)
				continue
			}
			seen := map[string]bool{}
			for _, c := range cols {
				if !isIdent(c) {
					add("%s %d: %q is not a valid column name", view, major, c)
				}
				if seen[c] {
					add("%s %d: column %q listed twice", view, major, c)
				}
				seen[c] = true
			}
			if prev, ok := owners[set]; ok && prev != view {
				add("%s %d: column set also used by %s (a shared set must be shared "+
					"between majors of one view, never between two views)", view, major, prev)
			}
			owners[set] = view
		}
	}

	// Every supported major must have data. A major in majors with no row at all
	// is how a half-finished table looks: the type checks pass and the collectors
	// silently collect nothing.
	for _, m := range majors {
		found := false
		for _, per := range table {
			if _, ok := per[m]; ok {
				found = true
				break
			}
		}
		if !found {
			add("major %d has no views in the matrix", m)
		}
	}

	switch len(errs) {
	case 0:
		return nil
	case 1:
		return fmt.Errorf("pgversion: %s", errs[0])
	default:
		return fmt.Errorf("pgversion: %d problems, first: %s", len(errs), errs[0])
	}
}

// checkViewName enforces the spelling a View must have: lowercase, underscore
// separated, pg_-prefixed. Every relation in the table matches, and the rule
// catches the two realistic typos — a schema-qualified value ("pg_catalog.pg_locks",
// which belongs in Query's FROM clause, not in the View) and a CamelCase value
// ("PgStatActivity", which would make two spellings of one view).
func checkViewName(view View) error {
	s := string(view)
	if s == "" {
		return fmt.Errorf("empty view name")
	}
	if strings.ContainsAny(s, ". ") {
		return fmt.Errorf("view name %q is schema-qualified; Schema() owns the qualifier", s)
	}
	if !strings.HasPrefix(s, "pg_") {
		return fmt.Errorf("view name %q does not start with pg_", s)
	}
	for _, r := range s {
		if r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '_' {
			continue
		}
		return fmt.Errorf("view name %q contains %q; PostgreSQL relation names are lowercase", s, r)
	}
	return nil
}

func isIdent(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		switch {
		case r >= 'a' && r <= 'z', r == '_':
		case r >= '0' && r <= '9' && i > 0:
		default:
			return false
		}
	}
	return true
}
